#include <vector>

using namespace std;

class Solution {
public:
    vector<int> countPoints(vector<vector<int>>& points, vector<vector<int>>& queries) {
        vector<int> res;
        for (auto& q : queries) {
            int x = q[0], y = q[1], r2 = q[2] * q[2], cnt = 0;
            for (auto& p : points) {
                int dx = p[0] - x, dy = p[1] - y;
                if (dx * dx + dy * dy <= r2) cnt++;
            }
            res.push_back(cnt);
        }
        return res;
    }
};
